(() => {
  const root=window.TitanWorkCore=window.TitanWorkCore||{}; const DB=()=>root.db,S=()=>root.contracts.stores;
  async function usage(){ const estimate=await navigator.storage?.estimate?.()||{}; const attachments=await DB().all(S().attachments),knowledge=await DB().all(S().knowledgeArticles),packs=await DB().all(S().offlinePacks),records=await DB().all(S().records),outbox=await DB().all(S().outbox); const jsonBytes=v=>new Blob([JSON.stringify(v)]).size; const used=estimate.usage||0,quota=estimate.quota||0,ratio=quota?used/quota:0; return {used,quota,ratio,pressure:ratio>=0.9?'critical':ratio>=0.75?'warning':'normal',persisted:await navigator.storage?.persisted?.(),categories:{pendingUploads:attachments.filter(a=>a.state!=='synced').reduce((n,a)=>n+(a.size||0),0),syncedAttachments:attachments.filter(a=>a.state==='synced').reduce((n,a)=>n+(a.size||0),0),knowledge:jsonBytes(knowledge),conversationCache:jsonBytes(records),offlinePacks:jsonBytes(packs),outbox:jsonBytes(outbox)}}; }
  async function requestPersistent(){return navigator.storage?.persist?navigator.storage.persist():false;}
  async function cleanup({preview=true,attachmentDays=30,removeExpiredPacks=true}={}){ const result={attachments:await root.attachments.cleanupSynced({olderThanDays:attachmentDays,preview:true}),packs:removeExpiredPacks?await root.offlinePacks.expired():[]}; if(!preview){for(const pack of result.packs)await root.offlinePacks.remove(pack.id);await root.attachments.cleanupSynced({olderThanDays:attachmentDays,preview:false});} return result; }
  async function ensureCapacity(requiredBytes=0,{reserveRatio=0.1}={}){const info=await usage();if(!info.quota)return {ok:true,...info};const available=Math.max(0,info.quota-info.used-(info.quota*reserveRatio));return {ok:available>=requiredBytes,available,requiredBytes,...info};}
  root.storageManager={usage,requestPersistent,cleanup,ensureCapacity};
})();
